def get_user_orders(db, user_id, status=None):
    q = "SELECT * FROM orders WHERE user_id = " + str(user_id)
    if status:
        q += " AND status = '" + status + "'"
    rows = db.execute(q).fetchall()
    result = []
    for r in rows:
        d = {}
        d['id'] = r[0]
        d['total'] = r[3]
        d['status'] = r[5]
        result.append(d)
    return result
